const AI_SPAWNER_ID = 9;

export function OnGameModeStarted(): void {
    const spawner = mod.GetSpawner(AI_SPAWNER_ID);

    // Class and team are optional. Without them the bot takes the spawner defaults.
    mod.SpawnAIFromAISpawner(spawner, mod.SoldierClass.Assault, mod.GetTeam(2));
}

const AI_SPAWNER_IDS = [1, 2, 3, 4];

export async function OnGameModeStarted(): Promise<void> {
    for (const id of AI_SPAWNER_IDS) {
        mod.SpawnAIFromAISpawner(mod.GetSpawner(id), mod.SoldierClass.Assault, mod.GetTeam(2));

        // One spawn per spawner per tick. The wait puts the next call on a later tick.
        await mod.Wait(0.5);
    }
}

export function OnSpawnerSpawned(eventPlayer: mod.Player, eventSpawner: mod.Spawner): void {
    // Standard bot brain: the bot pushes objectives and fights back.
    mod.AIBattlefieldBehavior(eventPlayer);

    // For a shooting range use this instead:
    // mod.AIIdleBehavior(eventPlayer);
    console.log(`bot deployed from spawner ${mod.GetObjId(eventSpawner)}`);
}

// Object ids of small SpatialObjects placed along the route in the map editor.
const PATROL_IDS = [301, 302];
let nextLeg = 0;

function sendToNextLeg(player: mod.Player): void {
    const target = mod.GetObjectPosition(mod.GetSpatialObject(PATROL_IDS[nextLeg]));
    nextLeg = (nextLeg + 1) % PATROL_IDS.length;
    mod.AIMoveToBehavior(player, target);
}

export async function OnSpawnerSpawned(eventPlayer: mod.Player): Promise<void> {
    await mod.Wait(3);
    sendToNextLeg(eventPlayer);
}

export function OnAIMoveToSucceeded(eventPlayer: mod.Player): void {
    sendToNextLeg(eventPlayer);
}

export function OnAIMoveToFailed(eventPlayer: mod.Player): void {
    // No path. Park the bot rather than hammering it with more orders.
    mod.AIIdleBehavior(eventPlayer);
}

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    if (!mod.GetSoldierState(eventPlayer, mod.SoldierStateBool.IsAISoldier)) return;

    mod.AIEnableShooting(eventPlayer, false);
    mod.AIEnableTargeting(eventPlayer, false);
    mod.AIIdleBehavior(eventPlayer);
}

const AI_SPAWNER_ID = 9;
const BOTS_WANTED = 4;

function countBots(): number {
    const players = mod.AllPlayers();
    let bots = 0;

    for (let i = 0; i < mod.CountOf(players); i++) {
        const player: mod.Player = mod.ValueInArray(players, i);
        if (mod.GetSoldierState(player, mod.SoldierStateBool.IsAISoldier)) bots++;
    }

    return bots;
}

export async function OnGameModeStarted(): Promise<void> {
    const spawner = mod.GetSpawner(AI_SPAWNER_ID);

    mod.AISetUnspawnOnDead(spawner, false);
    mod.SetUnspawnDelayInSeconds(spawner, 300);

    for (let i = 0; i < BOTS_WANTED; i++) {
        mod.SpawnAIFromAISpawner(spawner);
        await mod.Wait(0.5);
    }
}

export async function OnPlayerLeaveGame(eventNumber: number): Promise<void> {
    await mod.Wait(1);
    if (countBots() >= BOTS_WANTED) return;

    mod.SpawnAIFromAISpawner(mod.GetSpawner(AI_SPAWNER_ID));
}

// Object variables are addressed by index, the same numbering the blocks editor uses.
const HomeSpawnerPlayerVar = 0;

export function OnSpawnerSpawned(eventPlayer: mod.Player, eventSpawner: mod.Spawner): void {
    mod.SetVariable(mod.ObjectVariable(eventPlayer, HomeSpawnerPlayerVar), mod.GetObjId(eventSpawner));
}

export function OnPlayerDied(eventPlayer: mod.Player): void {
    if (!mod.GetSoldierState(eventPlayer, mod.SoldierStateBool.IsAISoldier)) return;

    const spawnerId: number = mod.GetVariable(mod.ObjectVariable(eventPlayer, HomeSpawnerPlayerVar));
    console.log(`bot died, its spawner was ${spawnerId}`);
}

const VEHICLE_SPAWNER_ID = 2;
let pendingPilot: mod.Player | undefined;

export function OnPlayerInteract(eventPlayer: mod.Player): void {
    // Remember who asked. The call below hands nothing back.
    pendingPilot = eventPlayer;
    mod.ForceVehicleSpawnerSpawn(mod.GetVehicleSpawner(VEHICLE_SPAWNER_ID));
}

export function OnVehicleSpawned(eventVehicle: mod.Vehicle): void {
    if (pendingPilot === undefined) return;
    if (mod.IsVehicleOccupied(eventVehicle)) return;

    mod.ForcePlayerToSeat(pendingPilot, eventVehicle, 0);
    pendingPilot = undefined;
}

const BLOCKED_SEAT = 1;

export function OnPlayerEnterVehicleSeat(eventPlayer: mod.Player, eventVehicle: mod.Vehicle): void {
    const seat = mod.GetPlayerVehicleSeat(eventPlayer);
    if (seat !== BLOCKED_SEAT) return;

    // Prefer a free seat, otherwise put them back on the ground.
    if (!mod.IsVehicleSeatOccupied(eventVehicle, 0)) {
        mod.ForcePlayerToSeat(eventPlayer, eventVehicle, 0);
        return;
    }

    mod.ForcePlayerExitVehicle(eventPlayer, eventVehicle);
}

const VEHICLE_SPAWNER_ID = 2;

export function OnGameModeStarted(): void {
    const spawner = mod.GetVehicleSpawner(VEHICLE_SPAWNER_ID);

    mod.SetVehicleSpawnerVehicleType(spawner, mod.VehicleList.UH60);
    mod.SetVehicleSpawnerRespawnTime(spawner, 30);
    mod.SetVehicleSpawnerAutoSpawn(spawner, true);
}

// A spawner made during play cannot be configured on the tick it was made.
export async function addSpawnerAt(position: mod.Vector): Promise<void> {
    const spawner = mod.SpawnObject(
        mod.RuntimeSpawn_Common.VehicleSpawner,
        position,
        mod.CreateVector(0, 0, 0)
    ) as mod.VehicleSpawner;

    await mod.Wait(1);

    mod.SetVehicleSpawnerVehicleType(spawner, mod.VehicleList.UH60);
    mod.SetVehicleSpawnerAutoSpawn(spawner, true);
}

let ticks = 0;

export function OngoingPlayer(eventPlayer: mod.Player): void {
    if (!mod.GetSoldierState(eventPlayer, mod.SoldierStateBool.IsProne)) return;

    mod.DisplayNotificationMessage(mod.Message("Stay down"), eventPlayer);
}

export function OngoingGlobal(): void {
    ticks++;

    // 30 ticks is one second. Everything below runs once per second.
    if (ticks % 30 !== 0) return;

    console.log(`seconds left: ${mod.GetMatchTimeRemaining()}`);
}

let lastCondition = false;
let heartbeat = 0;

export function OngoingGlobal(): void {
    // The same edge test the blocks editor does for you.
    const condition = Math.round(mod.GetMatchTimeElapsed()) % 2 === 0;
    const rising = condition && !lastCondition;

    lastCondition = condition;
    if (!rising) return;

    heartbeat++;
    console.log(`heartbeat ${heartbeat}`);
}

const ROUND_SECONDS = 2700; // 45 minutes
let ended = false;

export function OnGameModeStarted(): void {
    mod.SetGameModeTimeLimit(ROUND_SECONDS);
}

export function OngoingGlobal(): void {
    if (ended) return;
    if (mod.GetMatchTimeRemaining() >= 1) return;

    ended = true;
    mod.EndGameMode(mod.GetTeam(2));
}

// One value for the whole match.
const RoundNumberGlobalVar = mod.GlobalVariable(0);

// One value per player. Object variables are addressed by index.
const KillsPlayerVar = 0;

export function OnGameModeStarted(): void {
    mod.SetVariable(RoundNumberGlobalVar, 1);
}

export function OnPlayerEarnedKill(eventPlayer: mod.Player): void {
    const kills: number = mod.GetVariable(mod.ObjectVariable(eventPlayer, KillsPlayerVar));
    mod.SetVariable(mod.ObjectVariable(eventPlayer, KillsPlayerVar), kills + 1);

    console.log(`round ${mod.GetVariable(RoundNumberGlobalVar)}, kills ${kills + 1}`);
}

function toList(array: mod.Array): mod.Player[] {
    const out: mod.Player[] = [];
    const size = mod.CountOf(array);

    for (let i = 0; i < size; i++) {
        out.push(mod.ValueInArray(array, i));
    }

    return out;
}

export function OnGameModeStarted(): void {
    // Engine style: counted loop over the handle.
    const players = mod.AllPlayers();
    let bots = 0;

    for (let i = 0; i < mod.CountOf(players); i++) {
        const player: mod.Player = mod.ValueInArray(players, i);
        if (mod.GetSoldierState(player, mod.SoldierStateBool.IsAISoldier)) bots++;
    }

    // JavaScript style: copy out once, then use normal array methods.
    const alive = toList(mod.AllPlayers()).filter(
        p => !mod.GetSoldierState(p, mod.SoldierStateBool.IsDead)
    );

    // AppendToArray returns a NEW array. Assigning the result back is required.
    let picked = mod.EmptyArray();
    if (alive.length > 0) picked = mod.AppendToArray(picked, alive[0]);

    console.log(`bots ${bots}, alive ${alive.length}, picked ${mod.CountOf(picked)}`);
}
